      "فرح المؤمنين بالتوبة؛ فلما نزلت آيات القبول باركوا له، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "الصدق مع النفس؛ فاعترف بلا عذر، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الإقرار قبل الاستغفار."
