    full_content: `أبو هريرة — صحابي جليل، أكثر رواية للحديث، واشتهرت قصته في غزوة خيبر.

**الجوع:**
روى في صحيح البخاري أنه جاع يوم خيبر حتى وضع حجراً على بطنه.

**الصبر:**
صبر على الجوع في سبيل الله، ولم يشتكِ.

**العبرة:**
أبو هريرة يُذكّر أن الجهاد يحتاج إلى صبر على المشاق، وأن الأجر عند الله.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

ومن نفع هذا العرض أنه يربط المعلومة بسؤال التزكية والواقع العملي. والمقصود تقريب المعنى للمسلم المعاصر مع ضبط النقل والدليل؛ ويُراعى الأدب مع النصوص والتاريخ فلا يُزاد على ما ثبت`,
    key_lessons: [
      "الصبر على الجوع؛ فوضع حجراً على بطنه، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الصبر في سبيل الله.",
      "عدم الشكوى؛ فصبر ولم يشتكِ، ويُستفاد منه أن المؤمن يصبر بلا تذمر؛ مع مراعاة الدليل لا الشهرة.",
      "الأجر عند الله؛ فالصبر في سبيل الله مُثاب عليه، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "الجهاد يحتاج صبراً؛ فاشتهرت قصته في خيبر، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الاستعداد للمشاق."
    ],
    related_figures: ["النبي محمد ﷺ", "عمر بن الخطاب", "بلال بن رباح"],
    sources: ["صحيح البخاري", "صحيح مسلم", "الاستيعاب — ابن عبد البر"],
    tags: ["أبو هريرة", "خيبر", "صبر", "جهاد"],
    is_approved: true,
