    summary: "قصة سُمَيَّة بنت خياط رضي الله عنها وصبرها على عذاب أبي جهل حتى استُشهدت، والعبرة فيها أن الإيمان قد يُبتلى صاحبه بأشد الأذى، مع الاقتصار على الثابت في السيرة.",
    full_content: `سُمَيَّة بنت خياط — أم عمار بن ياسر، من أوائل من آمن، واشتهرت بصبرها على عذاب قريش.

**الابتلاء:**
روى في صحيح البخاري أن أبا جهل عذّبها على إسلامها مع أهل بيتها، فصبرت حتى استُشهدت.

**الشهادة:**
كانت أول شهيدة في الإسلام، وقد ذكرها النبي ﷺ في مواساته لأهل ياسر.

**العبرة:**
سُمَيَّة تُذكّر أن الإيمان قد يُبتلى صاحبه بأشد الأذى، وأن الصبر على الباطل من أعظم الأعمال.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

ومن هنا يحسن أن تُراجع المادة مع الشيخ أو المشرف عند الحاجة إلى التفصيل. والهدف تثبيت العلم النافع في القلب والسلوك`,
    key_lessons: [
      "الصبر على الأذى؛ فعذّبها أبو جهل ولم ترجع، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الشهادة في سبيل الله؛ فكانت أول شهيدة، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "مواساة أهل المبتلى؛ فذكرها النبي ﷺ، ويُذكّر أن نصرة المؤمن واجبة؛ مع الاقتصاد في الروايات.",
      "الإيمان يُرفع صاحبه؛ فاشتهرت بصبرها، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
