    category: "صحابة",
    era: "مدني",
    icon: "Flag",
    summary: "قصة مصعب بن عمير رضي الله عنه ودعوته في المدينة وشهادته يحمل راية المسلمين في أُحد، والعبرة فيها أن الشاب المؤمن قد يكون عموداً للدعوة، مع الاقتصار على الثابت في السيرة.",
    full_content: `مصعب بن عمير — من أوائل من آمن في مكة، واشتهر بورعه ودعوته في المدينة.

**الدعوة:**
بعثه النبي ﷺ إلى المدينة مع موسى بن عمير لتعليم أهلها القرآن والإسلام قبل الهجرة.

**الراية:**
حمل راية المسلمين في غزوة أُحد، فاستُشهد وهو يدافع عنها.

**العبرة:**
مصعب يُذكّر أن الشاب المؤمن قد يكون عموداً للدعوة، وأن الشهادة في سبيل الله أشرف من الدنيا.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وبهذا تبقى الصياغة خادمة للعلم لا مزاحمة للمصدر ولا متجاوزة لحدوده. ويُفرَّق بين ما هو تعبّدي ثابت وما هو تاريخي أو تربوي`,
    key_lessons: [
      "الدعوة قبل الهجرة؛ فعلّم أهل المدينة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى نشر العلم.",
      "الورع في الشباب؛ فاشتهر بزهده، ويُستفاد منه أن الإيمان يُرفع صاحبه؛ مع مراعاة الدليل لا الشهرة.",
      "الشهادة في سبيل الله؛ فاستُشهد يحمل الراية، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "الوفاء للرسالة؛ فبذل نفسه في أُحد، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على الدين."
    ],
