    summary: "قصة طلحة بن عبيد الله رضي الله عنه وكرمه وجهاده، والعبرة فيها أن المؤمن قد يُنفق ماله في سبيل الله ولا يبخل، مع الاقتصار على الثابت في السيرة.",
    full_content: `طلحة بن عبيد الله — من العشرة المبشرين بالجنة، واشتهر بكرمه وجهاده.

**الكرم:**
روى في صحيح البخاري أنه أنفق ماله في سبيل الله، وكان من أغنى الصحابة.

**الجهاد:**
شارك في المعارك وكان من أشجع الصحابة، واستُشهد في معركة الجمل.

**العبرة:**
طلحة يُذكّر أن الكرم في سبيل الله من أعظم الأعمال، وأن العبرة بالأثر لا بالشعار.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وبهذه الطريقة تصير القصة أو المادة بابًا لتربية النظر قبل تكرار الألفاظ. ويبقى المنهج: التحقق ثم البيان ثم التطبيق برفق؛ ولا يُجعل المشتهر أو الضعيف في مقام الثابت عند أهل التحقيق`,
    key_lessons: [
      "الكرم في سبيل الله؛ فأنفق ماله، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الجهاد في سبيل الله؛ فشارك في المعارك، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الشهادة في سبيل الله؛ فاستُشهد في الجمل، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "أبو بكر الصديق", "عمر بن الخطاب", "الزبير بن العوام"],
    sources: ["صحيح البخاري", "سير أعلام النبلاء — الذهبي", "الاستيعاب — ابن عبد البر"],
