    full_content: `خديجة بنت خويلد — أول من آمن بالنبي ﷺ، واشتهرت بدعمها وثباتها.

**الإيمان:**
روى في صحيح البخاري أنها كانت أول من آمن، وصدّقته حين كذّبه الناس.

**الدعم:**
أنفقت مالها في سبيل الدعوة، وكانت أول زوجات النبي ﷺ.

**العبرة:**
خديجة تُذكّر أن المرأة المؤمنة قد تكون سنداً لدعوة الحق، وأن الصبر على البلاء من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وتبقى الخلاصة أن العلم النافع يردّ صاحبه إلى تعظيم الوحي وحسن الاتباع. والمطلب تقريب الهداية لا تكثير الحشو بلا فائدة؛ ويبقى المنهج: التحقق ثم البيان ثم التطبيق برفق`,
    key_lessons: [
      "الإيمان والثبات؛ فآمنت أولاً، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الدعم في سبيل الله؛ فأنفقت مالها، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقيت مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الصبر على البلاء؛ فصبرت على الأذى، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "فاطمة بنت محمد", "علي بن أبي طالب", "زينب بنت خديجة"],
