    summary: "قصة بلال بن رباح رضي الله عنه وشجاعته ووفائه، والعبرة فيها أن المؤمن قد يُبتلى ولا يتنازل عن دينه، مع الاقتصار على الثابت في السيرة.",
    full_content: `بلال بن رباح — ابن عمة النبي ﷺ، واشتهر بشجاعته ووفائه.

**الشجاعة:**
روى في صحيح البخاري أنه كان أول من أظهر السيف في الإسلام، وشارك في المعارك.

**الوفاء:**
بقي مع النبي ﷺ في مكة والمدينة، وكان من العشرة المبشرين بالجنة.

**العبرة:**
بلال يُذكّر أن الشجاعة في سبيل الله من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وهذا المسلك أدعى إلى رسوخ الفائدة من سرد طويل لا يميّز بين الثابت والشائع. والمطلب تقريب الهداية لا تكثير الحشو بلا فائدة`,
    key_lessons: [
      "الشجاعة في الجهاد؛ فكان أول من أظهر السيف، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الصبر على البلاء؛ فابتُلي في طريقه، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الجهاد في سبيل الله؛ فشارك في المعارك، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "عبد الرحمن بن عوف", "علي بن أبي طالب", "عبد الله بن بلال"],
