    summary: "قصة أبي عبيدة بن الجراح رضي الله عنه وأمانته، والعبرة فيها أن الأمانة في القيادة من أعظم الأخلاق، مع الاقتصار على الثابت في السيرة.",
    full_content: `معاذ بن جبل — أمين هذه الأمة، واشتهر بأمانته وتواضعه.

**الأمانة:**
روى في صحيح البخاري أن النبي ﷺ سمّاه أمين هذه الأمة، وكان قائداً في الفتوح.

**التواضع:**
عُرف بتواضعه وعدم طلب المنصب، وكان من العشرة المبشرين بالجنة.

**العبرة:**
معاذ يُذكّر أن الأمانة في القيادة من أعظم الأخلاق، وأن التواضع من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

والانتفاع بها يكون بالتحقق والتأمل ثم تحويل المعنى إلى عادة صالحة. ويُراعى الأدب مع النصوص والتاريخ فلا يُزاد على ما ثبت؛ وتُقدَّم الرواية المحرَّرة على الحكايات التي لم تثبت`,
    key_lessons: [
      "الأمانة في القيادة؛ فسمّاه النبي ﷺ أمين الأمة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "التواضع في العلم؛ فعُرف بتواضعه، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الجهاد في سبيل الله؛ فقاد الفتوح، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
