    full_content: `عثمان بن عفان — من العشرة المبشرين بالجنة، واشتهر بكرمه وحيائه.

**الكرم:**
روى في صحيح البخاري أنه أنفق ماله في سبيل الله، وجهّز جيش العسرة.

**الحياء:**
عُرف بحيائه الشديد، وكان النبي ﷺ يُثني عليه في ذلك.

**العبرة:**
عثمان يُذكّر أن الكرم في سبيل الله من أعظم الأعمال، وأن الحياء من الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

ومن هنا يحسن أن تُراجع المادة مع الشيخ أو المشرف عند الحاجة إلى التفصيل. ولا يُجعل المشتهر أو الضعيف في مقام الثابت عند أهل التحقيق؛ والهدف تثبيت العلم النافع في القلب والسلوك`,
    key_lessons: [
      "الكرم في سبيل الله؛ فأنفق ماله، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الحياء من الإيمان؛ فعُرف بحيائه، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الجهاد في سبيل الله؛ فجهّز جيش العسرة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
