      "الوفاء للرسالة؛ فبقيت مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الدعوة بالعلم؛ فكان الصحابة يرسلون إليها، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
