    category: "صحابة",
    era: "مدني",
    icon: "Target",
    summary: "قصة سعد بن أبي وقاص رضي الله عنه وبراعته في الرماية وصبره على البلاء، والعبرة فيها أن المؤمن قد يُبتلى ولا يتنازل عن دينه، مع الاقتصار على الثابت في السيرة.",
    full_content: `سعد بن أبي وقاص — من أوائل من آمن، واشتهر ببراعته في الرماية وصبره على البلاء.

**الرماية:**
روى في صحيح مسلم أن النبي ﷺ دعا له قائلاً: «اللهم اجعل سهمه صائباً».

**الصبر:**
عُرف بصبره على البلاء، وكان من العشرة المبشرين بالجنة.

**العبرة:**
سعد يُذكّر أن الصبر على البلاء من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

فالخلاصة العملية تحفظ للقصة أو الدرس أثره من غير إفراط ولا جفاء. ويُحترز من الإسرائيليات أن تُساق مساق الحق المقطوع؛ ويُفرَّق بين ما هو تعبّدي ثابت وما هو تاريخي أو تربوي`,
    key_lessons: [
      "الصبر على البلاء؛ فعُرف بصبره، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الجهاد في سبيل الله؛ فشارك في المعارك، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الدعاء للمؤمن؛ فدعا له النبي ﷺ، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
