    title: "أم سلمة — حكمة وصبر",
    category: "صحابة",
    era: "مدني",
    icon: "BookOpen",
    summary: "قصة أم سلمة رضي الله عنها وحكمتها في الهجرة وصبرها على البلاء، والعبرة فيها أن المرأة المؤمنة قد تكون قدوة في الصبر والحكمة، مع الاقتصار على الثابت في السيرة.",
    full_content: `أم سلمة هند بنت أبي أمية — من أمهات المؤمنين، واشتهرت بحكمتها وصبرها على البلاء.

**الحكمة:**
روى في صحيح مسلم أنها نصحت النبي ﷺ حين أُمر بترك الحج بعد صلح الحديبية.

**الصبر:**
عُرفت بصبرها على فراق زوجها الأول أبي سلمة ووفائها للرسالة.

**العبرة:**
أم سلمة تُذكّر أن الحكمة في المواقف من أعظم الأخلاق، وأن الصبر على البلاء من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

ومن أحسن ثمراتها أن تصنع احترامًا للمصدر ووعيًا بحدود العبارة. ويُعرض المعنى بلغة واضحة تناسب المتعلم المعاصر`,
    key_lessons: [
      "الحكمة في المواقف؛ فنصحت النبي ﷺ، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الصبر على البلاء؛ فصبرت على فراق زوجها، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقيت مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "رواية الحديث؛ فروت عن النبي ﷺ، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "أبو سلمة بن عبد الأسد", "أبو بكر الصديق", "عائشة بنت أبي بكر"],
