    full_content: `خالد بن الوليد — سيف الله المسلول، واشتهر بقيادته في الجهاد وبراعته في القتال.

**القيادة:**
روى في صحيح البخاري أن النبي ﷺ قال: «سيف من سيوف الله».

**العدل:**
عُرف بمراعاته لضوابط الجهاد ووفائه للرسالة بعد إسلامه.

**العبرة:**
خالد يُذكّر أن القيادة في الجهاد من أعظم الأخلاق، وأن مراعاة العدل من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وهكذا تحفظ المادة مقصدها التعليمي من غير تحميل للنص ما لا يحتمله. ويُستفاد من هذا السياق في بناء الوعي الشرعي بلا غلو ولا تهاون؛ وكل زيادة بلا سند صحيح تُترك أو تُذكر مع بيان درجتها`,
