    summary: "قصة طلحة بن عبيد الله رضي الله عنه وكرمه في بيت مال المسلمين وصبره على الجراح في يوم الجمل، والعبرة فيها أن المؤمن قد يُؤتَى بسخاء في المال وثبات في الحق، مع الاقتصار على الثابت في السيرة.",
    full_content: `طلحة بن عبيد الله — من العشرة المبشرين بالجنة، واشتهر بكرمه ووفائه للرسالة.

**الكرم:**
روى في صحيح البخاري أنه كان من أكرم الصحابة، ويُذكر أنه أنفق ماله في سبيل الله.

**الشهادة:**
عُرف بصبره على الجراح في معارك الإسلام ووفائه للرسالة.

**العبرة:**
طلحة يُذكّر أن الكرم في المال من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وفي ذلك تدريب على الإنصاف العلمي وترك التهويل الذي يضعف الثقة بالمحتوى. ويُفرَّق بين ما هو تعبّدي ثابت وما هو تاريخي أو تربوي`,
    key_lessons: [
      "الكرم في المال؛ فأنفق في سبيل الله، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الصبر على الجراح؛ فصبر في المعارك، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الإيثار؛ فقدّم حقوق الآخرين، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "أبو بكر الصديق", "عمر بن الخطاب", "الزبير بن العوام"],
    sources: ["صحيح البخاري", "سير أعلام النبلاء — الذهبي", "الاستيعاب — ابن عبد البر"],
