    full_content: `عبد الرحمن بن عوف — من العشرة المبشرين بالجنة، واشتهر بتجارته وإنفاقه في سبيل الله.

**التجارة:**
روى في صحيح البخاري أنه كان من أغنى الصحابة، وكسب ماله بالحلال.

**الإنفاق:**
عُرف بإنفاقه في سبيل الله ووفائه للرسالة من أوّل الهجرة.

**العبرة:**
عبد الرحمن يُذكّر أن كسب الحلال والإنفاق في وجوه الخير من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

ومن نفع هذا العرض أنه يربط المعلومة بسؤال التزكية والواقع العملي. ويُعرض المعنى بلغة واضحة تناسب المتعلم المعاصر`,
    key_lessons: [
      "كسب الحلال؛ فتاجر بالحلال، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الإنفاق في سبيل الله؛ فأنفق ماله، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الزهد في الدنيا؛ فلم يُعلق قلبه بالمال، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
