    category: "صحابة",
    era: "مدني",
    icon: "Compass",
    summary: "قصة سلمان الفارسي رضي الله عنه وبحثه عن الحق من فارس إلى المدينة ووفائه للرسالة، والعبرة فيها أن طلب الحق قد يطول لكنه يُثمر إذا صُحب بالصبر، مع الاقتصار على الثابت في السيرة.",
    full_content: `سلمان الفارسي — من أبرز الصحابة الذين بحثوا عن الحق قبل لقاء النبي ﷺ.

**البحث:**
روى في صحيح البخاري أنه سافر طلباً للحق حتى أسلم.

**الوفاء:**
عُرف بوفائه للرسالة وحكمته في النصح.

**العبرة:**
سلمان يُذكّر أن طلب الحق يستحق الصبر، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

ومن تمام الفائدة أن تُقرأ في سياقها التاريخي أو العلمي بلا تعجل في الحكم. ويُحترز من الإسرائيليات أن تُساق مساق الحق المقطوع؛ والمطلب تقريب الهداية لا تكثير الحشو بلا فائدة؛ ويُستحضر عند القراءة أدب الخلاف وترك التعصب للروايات الضعيفة`,
    key_lessons: [
      "طلب الحق؛ فبحث حتى أسلم، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الصبر على البلاء؛ فصبر في طريقه، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الحكمة في النصح؛ فنصح للمسلمين، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "أبو ذر الغفاري", "عمار بن ياسر", "أبو بكر الصديق"],
