    title: "بلال بن رباح — أذان وصبر",
    category: "صحابة",
    era: "مكي",
    icon: "Bell",
    summary: "قصة بلال بن رباح رضي الله عنه وصبره على العذاب في مكة وكونه مؤذناً للنبي ﷺ، والعبرة فيها أن المؤمن قد يُبتلى في دينه ولا يتنازل عنه، مع الاقتصار على الثابت في السيرة.",
    full_content: `بلال بن رباح — من أوّل من أسلم، واشتهر بصبره على العذاب وكونه مؤذناً للنبي ﷺ.

**الصبر:**
روى في صحيح البخاري أنه صبر على العذاب في سبيل التوحيد.

**الأذان:**
عُرف بكونه أول مؤذن في الإسلام ووفائه للرسالة.

**العبرة:**
بلال يُذكّر أن الصبر على البلاء من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وهذا يفتح باب الأسئلة المنضبطة التي تزيد الفهم ولا تصنع دعاوى جديدة. وهذا باب من أبواب النصح العام لأهل القرآن والسنة؛ والعبرة بالاتباع والعمل لا بالانبهار بالروايات بلا تمحيص`,
    key_lessons: [
      "الصبر على العذاب؛ فصبر في مكة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الثبات على التوحيد؛ فلم يتنازل عن دينه، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "خدمة الدين؛ فكان مؤذناً، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "أبو بكر الصديق", "عمر بن الخطاب", "عمار بن ياسر"],
