    summary: "قصة أبي موسى الأشعري رضي الله عنه وقراءته للقرآن وورعه في الفصل بين الناس، والعبرة فيها أن المؤمن قد يُؤتَى علماً فيُبلّغه بأمانة، مع الاقتصار على الثابت في السيرة.",
    full_content: `أبو موسى الأشعري — من أجمل الصحابة صوتاً بالقرآن، واشتهر بورعه في الفصل بين الناس.

**القرآن:**
روى في صحيح البخاري أن النبي ﷺ أثنى على قراءته.

**الورع:**
عُرف بورعه في القضاء ووفائه للرسالة.

**العبرة:**
أبو موسى يُذكّر أن تلاوة القرآن من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

فالمقصود تقريب المعنى لا استبدال المصادر المطولة أو القطع بما لم يثبت. وكل زيادة بلا سند صحيح تُترك أو تُذكر مع بيان درجتها؛ ويُفرَّق بين ما هو تعبّدي ثابت وما هو تاريخي أو تربوي`,
    key_lessons: [
      "تلاوة القرآن؛ فقرأ بصوت حسن، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الورع في القضاء؛ فحكم بين الناس، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الأمانة في التبليغ؛ فعلّم الناس، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "معاذ بن جبل", "عبد الله بن مسعود", "أبو بكر الصديق"],
