    summary: "قصة أم سلمة رضي الله عنها وحكمتها في النصح للنبي ﷺ وصبرها على البلاء، والعبرة فيها أن المؤمنة قد تُؤتَى حكمةً فيُبلّغها بأمانة، مع الاقتصار على الثابت في السيرة.",
    full_content: `أم سلمة — من أمهات المؤمنين، واشتهرت بحكمتها في النصح للنبي ﷺ وصبرها على البلاء.

**الحكمة:**
روى في صحيح مسلم أنها نصحت النبي ﷺ في صلح الحديبية.

**الصبر:**
عُرفت بصبرها على فقد زوجها وأبنائها ووفائها للرسالة.

**العبرة:**
أم سلمة تُذكّر أن الحكمة في النصح من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وفي مثل هذا تتضح منزلة التدرج؛ فالفهم ثم التطبيق ثم المراجعة. ويُستحضر عند القراءة أدب الخلاف وترك التعصب للروايات الضعيفة؛ والعبرة بالاتباع والعمل لا بالانبهار بالروايات بلا تمحيص`,
    key_lessons: [
      "الحكمة في النصح؛ فنصحت النبي ﷺ، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الصبر على البلاء؛ فصبرت على فقد أهلها، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقيت مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الأمانة في التبليغ؛ فروت عن النبي ﷺ، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
