    title: "أبو عبيدة بن الجراح — أمانة وثقة",
    category: "صحابة",
    era: "مدني",
    icon: "ShieldCheck",
    summary: "قصة أبي عبيدة بن الجراح رضي الله عنه وأمانته في بيت مال المسلمين وثقة الصحابة به، والعبرة فيها أن المؤمن قد يُؤتَى أمانةً فيُحافظ عليها بصدق، مع الاقتصار على الثابت في السيرة.",
    full_content: `أبو عبيدة بن الجراح — من أوثق الصحابة عند النبي ﷺ، واشتهر بأمانته في إدارة بيت المال.

**الأمانة:**
روى في صحيح البخاري أن النبي ﷺ سمّاه أمين هذه الأمة.

**الثقة:**
عُرف بصدقه في القتال والإدارة ووفائه للرسالة.

**العبرة:**
أبو عبيدة يُذكّر أن الأمانة في المال والجهاد من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وهذا القدر يكفي لربط الموضوع ببرنامج تعليمي مأمون العبارة. والمقصود تقريب المعنى للمسلم المعاصر مع ضبط النقل والدليل؛ ويُراعى الأدب مع النصوص والتاريخ فلا يُزاد على ما ثبت`,
    key_lessons: [
      "الأمانة في بيت المال؛ فولّاه النبي ﷺ، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الصدق في القتال؛ فقاد المسلمين، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "التواضع رغم المكانة؛ فكان حليماً، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
