      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "خدمة الدين بالأذان؛ فأذّن في المدينة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
