    category: "صحابة",
    era: "مكي",
    icon: "Heart",
    summary: "قصة عمار بن ياسر رضي الله عنه وصبره على التعذيب في مكة مع أبويه، والعبرة فيها أن المؤمن قد يُبتلى فيُثبت على التوحيد، مع الاقتصار على الثابت في السيرة.",
    full_content: `عمار بن ياسر — من أوائل من أسلم، واشتهر بصبره على التعذيب في مكة مع أبويه.

**الصبر:**
روى في صحيح البخاري أن قريشاً عذّبوه وأبويه حتى قال ما لم يكن في قلبه، فأُخبر النبي ﷺ فقال: «إن عادوا فعد».

**الشهادة:**
عُرف بوفائه للرسالة واستشهاده في صفين.

**العبرة:**
عمار يُذكّر أن الصبر على البلاء من أعظم الأخلاق، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

ومن هنا كانت العناية بالمنهج جزءًا من العناية بالمعلومة نفسها. ويُستحضر عند القراءة أدب الخلاف وترك التعصب للروايات الضعيفة`,
    key_lessons: [
      "الصبر على التعذيب؛ فصبر في مكة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الرجوع إلى النبي ﷺ عند الاضطرار؛ فأُخبر النبي ﷺ، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الشهادة في سبيل الله؛ فاستشهد في صفين، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "بلال بن رباح", "سعد بن أبي وقاص", "خباب بن الأرت"],
