      "الصبر على البلاء؛ فصبرت على الهجرة، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقت مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حرّ؛ مع الاقتصاد في الروايات.",
      "الدعاء عند الشدة؛ فدعت عند فراق زوجها، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
