      "تفسير القرآن؛ ففسّر بأمانة، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حرّ؛ مع الاقتصاد في الروايات.",
      "نقل العلم؛ فعلّم الناس، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
