    title: "سلمان الفارسي — طلب ووفاء",
    category: "صحابة",
    era: "مدني",
    icon: "Compass",
    summary: "قصة سلمان الفارسي رضي الله عنه وطلبه للحق حتى لحق بالنبي ﷺ، والعبرة فيها أن طلب الحق يستحق الصبر والجهد، مع الاقتصار على الثابت في السيرة.",
    full_content: `سلمان الفارسي — من أبرز الصحابة في طلب الحق، واشتهر بصبره حتى لحق بالنبي ﷺ.

**الطلب:**
روى في صحيح البخاري أنه سافر طلباً للحق حتى وصل إلى المدينة.

**الخندق:**
عُرف باقتراح حفر الخندق في غزوة الأحزاب، ووفائه للرسالة.

**العبرة:**
سلمان يُذكّر أن طلب الحق يستحق الصبر، وأن الوفاء للرسالة من تمام الإيمان.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وفي ذلك تدريب على الإنصاف العلمي وترك التهويل الذي يضعف الثقة بالمحتوى. ولا يُجعل المشتهر أو الضعيف في مقام الثابت عند أهل التحقيق؛ وهذا باب من أبواب النصح العام لأهل القرآن والسنة`,
    key_lessons: [
      "طلب الحق؛ فسافر حتى لحق بالنبي ﷺ، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الصبر على المحن؛ فصبر في طريقه، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الاجتهاد في النصرة؛ فاقترح الخندق، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
    related_figures: ["النبي محمد ﷺ", "أبو بكر الصديق", "عمر بن الخطاب", "علي بن أبي طالب"],
