    summary: "قصة مصعب بن عمير رضي الله عنه ودعوته في المدينة قبل الهجرة، والعبرة فيها أن الشاب المؤمن قد يُؤتَى حكمةً فيُثبت على التوحيد، مع الاقتصار على الثابت في السيرة.",
    full_content: `مصعب بن عمير — من أوائل من أسلم في مكة، واشتهر بدعوته الحكيمة في المدينة.

**الدعوة:**
روى في صحيح البخاري أن النبي ﷺ بعثه إلى المدينة لتعليم الناس القرآن قبل الهجرة.

**الشهادة:**
عُرف بشجاعته في أحد حتى استُشهد وهو يحمل لواء المسلمين.

**العبرة:**
مصعب يُذكّر أن طلب العلم والدعوة لا يُقيَّدان بالسن، وأن الوفاء للرسالة قد يبلغ صاحبه الشهادة.

تُقرأ هذه السيرة بوصفها شاهدًا على أثر الإيمان في صناعة الشخصية؛ فلا يقتصر النظر على اسم الصحابي أو شهرته، بل يُربط بين الموقف والعبادة والخلق والصدق في النصرة. ويُراعى عند عرضها ألا تُزاد أخبار لا يثبت أصلها، وأن يُفرّق بين ما صح في كتب الحديث والسير وما شاع في الوعظ أو القصص.

وبذلك يجد المتعلم مدخلًا واضحًا للمراجعة والمذاكرة وبناء الخلق. ويُراعى الأدب مع النصوص والتاريخ فلا يُزاد على ما ثبت`,
    key_lessons: [
      "الدعوة بالحكمة؛ فعلّم أهل المدينة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الشجاعة في سبيل الله؛ فحمل اللواء في أحد، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الزهد في الدنيا؛ فكان قليلاً منها، ويُذكّر أن الإيمان قرارٌ حرّ؛ مع الاقتصاد في الروايات.",
      "الوفاء للرسالة؛ فبقي على الإسلام، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
