    "icon": "Handshake",
    "summary": "قصة صلح الحديبية، وفيها درس الثقة بوعد الله حين تخفى الحكمة في أول الأمر.",
    "full_content": "خرج النبي ﷺ وأصحابه إلى مكة يريدون العمرة لا القتال، فمنعتهم قريش عند الحديبية، وطال التفاوض حتى كتب الصلح بشروط شق بعضها على نفوس الصحابة. بدا ظاهر الأمر أن المسلمين رجعوا بلا طواف، وأن في بعض البنود تنازلا مؤلما، لكن الوحي سماه فتحا مبينا؛ لأن الصلح أوقف الحرب وفتح باب الدعوة، فدخل الناس في الإسلام أفواجا، وتهيأت بعده أحداث عظيمة كان منها فتح مكة.\n\n**بصيرة القائد وثبات الجماعة:**\nفي الحديبية يظهر أن فقه المصلحة لا يعني ترك الثوابت، بل معرفة الطريق الذي يحقق مقاصد الشرع بأقل مفسدة. ثبت النبي ﷺ على أمر ربه، وعلّم أصحابه أن العبرة ليست بصورة الموقف العاجلة، بل بما يترتب عليه من حفظ الدين وظهور الحق. كما يظهر فضل أم سلمة رضي الله عنها في مشورتها حين تأخر الناس عن التحلل، فكان الرأي الحكيم بابا لانفراج الموقف.\n\n**العبرة:**\nتعلمنا الحديبية أن المؤمن قد يرى المنع فيحسبه خسارة، ثم يظهر أنه باب فتح ورحمة. وتعلمنا أن الطاعة عند اشتباه المصالح تحتاج ثقة وصبرا، وأن الشورى الصادقة تثبت العمل. ومن فقه القصة ألا نتعجل الحكم على النوازل من ظاهرها الأول، بل نردها إلى الدليل، ونراعي المآلات، ونحفظ وحدة الصف بلا تفريط في الحق.",
    "key_lessons": [
      "قد يكون الفتح في صورة منع مؤقت.",
      "فقه المآلات يضبط الحماسة ويصون المقاصد.",
      "الشورى الصالحة تعين على تجاوز لحظات الاضطراب.",
      "الثقة بوعد الله لا تلغي الأخذ بالأسباب."
    ],
    "related_figures": [
      "النبي محمد ﷺ",
      "أم سلمة",
      "قريش"
    ],
    "sources": [
      "سورة الفتح",
      "صحيح البخاري",
      "زاد المعاد"
    ],
