    "icon": "Moon",
    "summary": "الإسراء والمعراج أصلٌ ثابت في الوحي والسنة؛ الزوائد القصصية تُذكر بتحفّظ بعد التمحيص.",
    "full_content": "الإسراء والمعراج من أعظم دلائل النبوة الثابتة الاتجاه: أسري بالنبي ﷺ من المسجد الحرام إلى المسجد الأقصى، ثم عُرج به إلى السماء، كما دلّ عليه القرآن والسنة الصحيحة المعنى في الجملة. والمتعلم يقدّم هذا الأصل الإيماني بلا تردّد في ثبوت الحدث عند أهل السنة، ثم يتحفّظ في تفاصيل الوصف والدرجات والحوارات المطوّلة التي شاعت في بعض كتب السيرة والقصص ولم تبلغ كلها رتبة الجزم. فالمعجزة ثابتة، والسرد الزائد يحتاج تمييزًا.\n\n**منهج السيرة بلا غلو ولا جحود:**\nلا يُنكر أصل الإسراء والمعراج الثابت، ولا يُحوَّل كل تفصيل وعظي إلى عقيدة مقطوعة. يُقرأ خبر البخاري ومسلم وما قاربهما في الصحة، ويُذكر المشهور من كتب الدلائل بتحفّظ، ويُترك الاحتجاج بالواهي على مسائل الاعتقاد أو الفقه. وهذا أدبٌ مع الوحي ومع علم الرواية معًا.\n\n**خلق عند الذكر:**\nيُستخرج من الحدث تعظيم منازل الأنبياء، وصدق النبي ﷺ حين أخبر قومه فكذّبه المكذب وصدّقه الصدّيق، وربط الرحلة بفرض الصلاة كما يأتي. المحبة تظهر بالتصديق المنضبط لا بالمبالغة في صور لم تُحرَّر.\n\n**العبرة:**\nالإسراء والمعراج يثبتان النبوة ويربّيان على تعظيم الصلاة والتصديق، والتثبت يحفظ السيرة من اختلاط الثابت بالزائد.",
    "key_lessons": [
      "أصل الإسراء والمعراج ثابت في الوحي والسنة.",
      "الزوائد القصصية تُذكر بتحفّظ بعد التمحيص.",
      "لا جحود للأصل ولا غلو في غير المحرَّر.",
      "التصديق المنضبط من أدب محبة النبي ﷺ."
    ],
