    "icon": "Brick",
    "summary": "وضع الحجر الأسود درس جمع كلمة؛ الثابت الاتجاه يُقدَّم، وصور النزاع تُضبط بالمنهج.",
    "full_content": "قبل البعثة بزمنٍ اختلفت بطون قريش فيمن يضع الحجر الأسود عند تجديد بناء الكعبة، حتى كادوا يقتتلون، ثم رضوا بتحكيم أول داخل، فكان محمد ﷺ، فوضع الحجر في رداء وأمر كل قبيل أن يحمل بطرفٍ ثم وضعه بيده في موضعه. المعنى مشهور ثابت الاتجاه في مصادر السيرة: حكمةٌ رفعت القتال، ومكانةٌ للأمين قبل الوحي. وأما بعض تفاصيل أيام البناء وأعداد الحجر وطول الخصومة في الروايات فتُذكر بعد التمحيص بلا قطع بكل زيادة وعظية.\n\n**فقه جمع الكلمة:**\nالقصة تعلّم رفع النزاع بما يحفظ الكرامة للجميع، لا بإذلال طرف. والمتعلم يأخذ أن الحكمة قبل القوة في مواضع الإصلاح، وأن الأمانة التي عُرف بها النبي ﷺ مهّدت لقبول حكمه. لا تُحوَّل الحكاية إلى جدل معماري عن الكعبة يغني عن المقصود الأخلاقي.\n\n**منهج بلا غلو:**\nلا يُنكر الخبر المشهور المحرَّر في كتب السيرة المعتمدة بعد التمييز، ولا يُزاد عليه من الواهي ما يُخرج الواقعة عن أدب النقل. يُستخرج خلق العدل والحكمة، ويُترك الجزم بما لم يثبت من الزوائد.\n\n**العبرة:**\nجمع القلوب على معروفٍ أبقى من الانتصار لعصبية، ووضع الحجر معلَم حكمةٍ قبل الرسالة.",
    "key_lessons": [
      "وضع الحجر درس جمع كلمة مشهور الاتجاه.",
      "الأمانة مهّدت لقبول حكم النبي ﷺ.",
      "تفاصيل الخصومة تُحرَّر بلا غلو.",
      "الحكمة ترفع القتال قبل أن يقع."
    ],
