    "title": "ضيافة الوفود في المسجد",
    "category": "سيرة",
    "era": "نبوي",
    "icon": "Users",
    "summary": "إكرام الوفود هديٌ ثابت الاتجاه؛ يُميَّز عن الإسراف، والزوائد تُضبط.",
    "full_content": "استقبل النبي ﷺ وفود القبائل بعد الفتح وفي أزمنة متفرّقة، وكان للمسجد النبوي دورٌ في نزول بعضهم وتعليمهم وإكرامهم بما تيسّر. المعنى ثابت الاتجاه في مصادر السيرة بعد التمحيص: الضيافة خلقٌ نبوي وإبلاغٌ للدين لا مجرّد طعام. وأما تحويل كل وفدٍ إلى روايةٍ مطوّلة بأسماء أطباقٍ وأرقام ذبائح لم تُحرَّر، وبعض مشاهد المفاخرة المتأخرة، فموضع ردٍّ أو تحفّظ عند المحققين.\n\n**ضيافة بلا سرف:**\nالمتعلم يأخذ أن إكرام الضيف مشروعٌ محمود، وأن الإسراف والمباهاة ليسا من السيرة، وأن تعليم الوافد أحكام الدين أولى من الزينة الفارغة. السيرة تجمع بين الكرم وبين البلاغ.\n\n**منهج العقيدة والحديث:**\nيُقدَّم ما صحّ من أخبار الوفود، ويُحذر من اختلاط الكرم بالرياء أو بالبدع الاجتماعية. لا تُبنى عادة إسرافٍ على قصص واهية، ولا يُنكر أصل الضيافة الثابت.\n\n**العبرة:**\nضيافة الوفود تربّي على الكرم والتعليم معًا، مع سؤال أهل العلم عند الاشتباه في صور الولائم المعاصرة.",
