    "id": 490,
    "slug": "story-r145-2",
    "title": "وفد يفد إلى المدينة للتعلّم",
    "category": "سيرة",
    "era": "نبوي",
    "icon": "Users",
    "summary": "استقبال الوفود أدب دعوةٍ؛ الثابت يُقدَّم، وتفاصيل كل وفدٍ زائدة تُضبط.",
    "full_content": "وفد إلى النبي ﷺ وفودٌ من العرب يتعلمون ويبايعون على الوجه المقرَّر في السنّة والسيرة بعد التمحيص، فكان الاستقبال تعليمًا ورفقًا لا إذلالًا. المعنى ثابت الاتجاه: البلاغ يحتاج حسن استقبالٍ وصبرًا على سؤال المتعلّم. وأما تعيين كل جملةٍ في كل وفدٍ بقصص وعظية مطوّلة لم تُحرَّر، وصور الهدايا والأعداد المبالغ فيها، فتُذكر بتحفّظ؛ يُقدَّم الأصل، وتُترك الزوائد.\n\n**وفادة بلا تبجّح:**\nالمتعلم يأخذ أن تعليم الوافد يحتاج رفقًا وبيانًا، وأن الضيافة لا تكون ميدان مفاخرة، وأن النوازل الدعوية المعاصرة تُرجع إلى أهل العلم لا إلى الارتجال. السيرة تربّي على البلاغ الحسن لا على استعراض القوة باسم الدعوة.\n\n**منهج المصادر:**\nيُرجع إلى الصحيح في أبواب الوفود والمناقب، ويُقال: ثبت أصل الاستقبال والتعليم، والزوائد الوعظية تُميَّز. لا تُستبدل أحكام الدعوة بقصّة مرسلة عن وفدٍ معيّن لم يُحرَّر.\n\n**العبرة:**\nوفود المدينة تحفظ أدب البلاغ، والسيرة تُقرأ للتعليم المنضبط لا للمبالغات القصصية.",
