    "full_content": "هاجر النبي ﷺ من مكة إلى المدينة، وكانت الهجرة مفصلًا عظيمًا في قيام الجماعة المؤمنة وانتقال الدعوة إلى طورٍ جديد. أصل الحدث ثابتٌ في القرآن والسنة والسيرة، وفيه الأخذ بالأسباب والتوكل والصبر على فراق الوطن لله. وأما كثيرٌ من تفاصيل الطريق، وترتيب بعض المشاهد، وتعيين كل موضعٍ أو كلمةٍ في الرحلة، فذلك مما تتفاوت فيه الروايات ويحتاج إلى تمحيص قبل الجزم.\n\n**أسباب وتوكل:**\nالمتعلم يرى أن الهجرة ليست قصة فرارٍ عادي، بل عبوديةٌ وتدبيرٌ مشروعٌ تحت الوحي. الأخذ بالأسباب لا يناقض التوكل، وكتمان ما يحتاج الكتمان من باب الحكمة لا من باب الخوف المذموم.\n\n**لا غلو في المشاهد:**\nتُذكر المعاني الثابتة: النصرة، الصبر، صحبة المؤمنين، وبناء المجتمع. أما الحكايات الزائدة التي تُبنى عليها مواعظ مطلقة أو أرقام محددة أو مواضع لا تثبت، فتُعرض على مصادر السيرة والحديث قبل اعتمادها.\n\n**العبرة:**\nالهجرة تعلّم أن الطريق إلى الحق يجمع بين ثبات الوجهة وحسن السبب، وأن التمحيص يحميها من الزوائد.",
